#include "rpl-backup.h"
#include <assert.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Stock HP50g 2.15, generated by 123 :0:PORTZERO STO, 456 :1:PORTONE STO,
 * and 789 :2:PORTTWO STO. Low nibble first; captured after normal native
 * return. The originals remain in the corresponding RAM/Flash ports. */
static const char *const backups[] = {
    "26b20130008005f42545a55425f48041620900003210119200f9e3",
    "26b20f20007005f42545f4e4547041620900006540119200c144",
    "26b20f20007005f425454575f470416209000098701192002d43",
};

struct image
{
    uint8_t nibbles[64];
    uint32_t size;
    uint32_t base;
    uint32_t fail_at;
};

static int read_nibble(void *context, uint32_t address, uint8_t *value)
{
    struct image *image = context;
    if (address < image->base || address - image->base >= image->size || address == image->fail_at)
        return 0;
    *value = image->nibbles[address - image->base];
    return 1;
}

static void load(struct image *image, const char *text)
{
    *image = (struct image){.size = (uint32_t)strlen(text), .base = 0x81000u};
    for (uint32_t i = 0; i < image->size; ++i)
        image->nibbles[i] = text[i] <= '9' ? text[i] - '0' : text[i] - 'a' + 10;
}

int main(void)
{
    struct image image;
    struct hpclang_rpl_reader reader = {read_nibble, &image};
    for (uint32_t i = 0; i < 3; ++i) {
        load(&image, backups[i]);
        struct hpclang_rpl_backup_view view = {0};
        assert(hpclang_rpl_backup_view(&reader, image.base, image.size, &view) == 0);
        assert(view.span == image.size);
        assert(view.name_length == (i == 0 ? 8u : 7u));
        assert(view.name_address == image.base + 12);
        assert(view.value_address == image.base + 14 + 2 * view.name_length);
        uint8_t name[255];
        for (uint32_t j = 0; j < view.name_length; ++j) {
            uint32_t at = view.name_address - image.base + 2u * j;
            name[j] = image.nibbles[at] | (image.nibbles[at + 1u] << 4u);
        }
        uint8_t *packed = NULL;
        uint32_t encoded_span = 0;
        assert(hpclang_rpl_backup_encode(&reader, view.value_address, view.value_span, name,
                                         view.name_length, &packed, &encoded_span) == 0);
        assert(encoded_span == image.size);
        for (uint32_t j = 0; j < encoded_span; ++j)
            assert(((packed[j / 2u] >> ((j & 1u) * 4u)) & 15u) == image.nibbles[j]);
        free(packed);
        packed = NULL;
        encoded_span = 0x12345u;
        image.fail_at = view.value_address + view.value_span - 1u;
        assert(hpclang_rpl_backup_encode(&reader, view.value_address, view.value_span, name,
                                         view.name_length, &packed,
                                         &encoded_span) == HPCLANG_RPL_SPAN_UNAVAILABLE);
        assert(packed == NULL && encoded_span == 0x12345u);
        image.fail_at = 0;
        assert(hpclang_rpl_backup_encode(&reader, view.value_address, view.value_span, NULL, 1,
                                         &packed, &encoded_span) == HPCLANG_RPL_SPAN_MALFORMED);
        assert(hpclang_rpl_backup_encode(&reader, view.value_address, view.value_span, name, 256,
                                         &packed, &encoded_span) == HPCLANG_RPL_SPAN_MALFORMED);
        assert(hpclang_rpl_backup_encode(&reader, view.value_address, UINT32_MAX, name,
                                         view.name_length, &packed,
                                         &encoded_span) == HPCLANG_RPL_SPAN_BOUNDS);
        assert(hpclang_rpl_backup_encode(&reader, view.value_address, view.value_span + 1, name,
                                         view.name_length, &packed,
                                         &encoded_span) == HPCLANG_RPL_SPAN_MALFORMED);
        assert(packed == NULL && encoded_span == 0x12345u);
        assert(view.value_span == 14);
        const uint32_t checksums[] = {0x3e9f0, 0x441c0, 0x34d20};
        assert(view.checksum == checksums[i]);

        /* Every truncation must fail without publishing a partial result. */
        for (uint32_t limit = 0; limit < image.size; ++limit) {
            struct hpclang_rpl_backup_view before = view;
            assert(hpclang_rpl_backup_view(&reader, image.base, limit, &view) != 0);
            assert(memcmp(&view, &before, sizeof(view)) == 0);
        }
        image.fail_at = image.base + image.size - 1;
        assert(hpclang_rpl_backup_view(&reader, image.base, image.size, &view) ==
               HPCLANG_RPL_SPAN_UNAVAILABLE);
        /* A changed name or contained value must not bypass the native CRC. */
        const uint32_t corrupt[] = {12, view.value_address - image.base + 10, image.size - 1};
        for (uint32_t j = 0; j < 3; ++j) {
            load(&image, backups[i]);
            image.nibbles[corrupt[j]] ^= 1;
            assert(hpclang_rpl_backup_view(&reader, image.base, image.size, &view) ==
                   HPCLANG_RPL_SPAN_MALFORMED);
        }
    }
    struct hpclang_rpl_backup_view view;
    const uint32_t malformed_offsets[] = {10, 28, 35, 44};
    for (uint32_t i = 0; i < 4; ++i) {
        load(&image, backups[0]);
        image.nibbles[malformed_offsets[i]] = 15;
        assert(hpclang_rpl_backup_view(&reader, image.base, image.size, &view) != 0);
    }
    load(&image, backups[0]);
    image.nibbles[0] = 0;
    assert(hpclang_rpl_backup_view(&reader, image.base, image.size, &view) ==
           HPCLANG_RPL_SPAN_UNSUPPORTED);
    assert(hpclang_rpl_backup_view(&reader, UINT32_MAX, image.size, &view) ==
           HPCLANG_RPL_SPAN_BOUNDS);
    assert(hpclang_rpl_backup_view(NULL, image.base, image.size, &view) ==
           HPCLANG_RPL_SPAN_MALFORMED);
    load(&image, backups[0]);
    image.base = 0x100000u - image.size;
    assert(hpclang_rpl_backup_view(&reader, image.base, UINT32_MAX, &view) == 0);
    ++image.base;
    assert(hpclang_rpl_backup_view(&reader, image.base, UINT32_MAX, &view) ==
           HPCLANG_RPL_SPAN_BOUNDS);
    return 0;
}
